/* Авторские варианты по стереометрии, с индивидуальными схемами. */
(()=>{
 const box=(a,b,h)=>({kind:'mesh',points:{A:[0,0,0],B:[a,0,0],C:[a,b,0],D:[0,b,0],A1:[0,0,h],B1:[a,0,h],C1:[a,b,h],D1:[0,b,h]},edges:[['A','B'],['B','C'],['C','D'],['D','A',true],['A1','B1'],['B1','C1'],['C1','D1'],['D1','A1'],['A','A1'],['B','B1'],['C','C1'],['D','D1',true]]});
 const pyramid=(a,h)=>({kind:'mesh',points:{A:[0,0,0],B:[a,0,0],C:[a,a,0],D:[0,a,0],O:[a/2,a/2,0],S:[a/2,a/2,h]},edges:[['A','B'],['B','C'],['C','D'],['D','A',true],['S','A'],['S','B'],['S','C'],['S','D']],aux:[['S','O',true]]});
 for(let i=0;i<100;i++){
  const group=Math.floor(i/10),k=i%10,a=k+2,b=3+k%4,h=3+3*(k%4),r=k+1;let title,question,answer,steps,solid,sourceId,plan;
  if(group===0){title='Объём параллелепипеда';question=`Рёбра прямоугольного параллелепипеда равны ${a}, ${b} и ${h}. Найди объём.`;answer=a*b*h;steps=[`Площадь основания: ${a}·${b} = ${a*b}.`,`Умножаем площадь основания на высоту ${h}.`,`V = ${a*b}·${h} = ${answer}.`];solid=box(a,b,h);sourceId=27076;plan='Найди площадь основания и умножь её на высоту.';}
  if(group===1){title='Площадь поверхности параллелепипеда';question=`Рёбра прямоугольного параллелепипеда равны ${a}, ${b} и ${h}. Найди площадь полной поверхности.`;answer=2*(a*b+a*h+b*h);steps=[`Три различные площади граней: ${a*b}, ${a*h}, ${b*h}.`,`Каждая такая грань встречается дважды.`,`S = 2·(${a*b}+${a*h}+${b*h}) = ${answer}.`];solid=box(a,b,h);sourceId=27054;plan='Сложи площади трёх разных граней и удвой сумму.';}
  if(group===2){title='Диагональ параллелепипеда';question=`Рёбра прямоугольного параллелепипеда равны ${a}, ${b} и ${h}. Найди квадрат длины его пространственной диагонали.`;answer=a*a+b*b+h*h;steps=[`Квадрат диагонали основания равен ${a}² + ${b}² = ${a*a+b*b}.`,`Диагональ тела — гипотенуза треугольника с этой диагональю основания и высотой.`,`d² = ${a*a+b*b} + ${h}² = ${answer}.`];solid=box(a,b,h);solid.aux=[['A','C',true],['A','C1',false]];sourceId=27060;plan='Примени теорему Пифагора дважды.';}
  if(group===3){title='Высота по объёму';question=`Объём прямоугольного параллелепипеда равен ${a*b*h}, стороны основания равны ${a} и ${b}. Найди высоту.`;answer=h;steps=[`Площадь основания равна ${a}·${b} = ${a*b}.`,`V = S основания · h, значит h = V/S основания.`,`h = ${a*b*h}/${a*b} = ${answer}.`];solid=box(a,b,h);sourceId=27078;plan='Раздели объём на площадь основания.';}
  if(group===4){title='Ребро куба';question=`Полная поверхность куба равна ${6*a*a}. Найди длину его ребра.`;answer=a;steps=[`У куба шесть равных квадратных граней: S = 6a².`,`a² = ${6*a*a}/6 = ${a*a}.`,`Поскольку ребро положительно, a = ${answer}.`];solid=box(a,a,a);sourceId=27060;plan='Вырази квадрат ребра через площадь шести граней.';}
  if(group===5){title='Объём цилиндра';question=`Радиус основания цилиндра равен ${r}, высота равна ${h}. Найди V/π, где V — объём цилиндра.`;answer=r*r*h;steps=[`Площадь основания цилиндра равна πr² = ${r*r}π.`,`Умножаем её на высоту: V = ${r*r}π·${h} = ${answer}π.`,`Следовательно, V/π = ${answer}.`];solid={kind:'cylinder',radius:r,height:h};sourceId=27045;plan='Объём цилиндра равен площади основания, умноженной на высоту.';}
  if(group===6){title='Боковая поверхность цилиндра';question=`Радиус основания цилиндра равен ${r}, высота равна ${h}. Найди S/π, где S — площадь боковой поверхности.`;answer=2*r*h;steps=[`Развёртка боковой поверхности — прямоугольник с длиной 2πr и высотой h.`,`S = 2π·${r}·${h} = ${answer}π.`,`Значит, S/π = ${answer}.`];solid={kind:'cylinder',radius:r,height:h};sourceId=27058;plan='Умножь длину окружности основания на высоту.';}
  if(group===7){title='Объём конуса';question=`Радиус основания конуса равен ${r}, высота равна ${h}. Найди V/π, где V — объём конуса.`;answer=r*r*h/3;steps=[`Объём конуса составляет треть произведения площади основания на высоту.`,`V = π·${r}²·${h}/3 = ${answer}π.`,`Следовательно, V/π = ${answer}.`];solid={kind:'cone',radius:r,height:h};sourceId=27094;plan='Примени формулу V = πr²h/3.';}
  if(group===8){title='Площадь поверхности шара';question=`Радиус шара равен ${r}. Найди S/π, где S — площадь его поверхности.`;answer=4*r*r;steps=[`Площадь поверхности шара: S = 4πr².`,`Подставляем радиус: S = 4π·${r}² = ${answer}π.`,`Поэтому S/π = ${answer}.`];solid={kind:'sphere'};sourceId=27059;plan='Подставь радиус в формулу площади поверхности шара.';}
  if(group===9){title='Объём квадратной пирамиды';question=`Основание пирамиды — квадрат со стороной ${a}; высота пирамиды равна ${h}. Найди объём.`;answer=a*a*h/3;steps=[`Площадь квадратного основания: ${a}² = ${a*a}.`,`Объём пирамиды — треть произведения площади основания на высоту.`,`V = ${a*a}·${h}/3 = ${answer}.`];solid=pyramid(a,h);sourceId=901;plan='Найди площадь основания и примени формулу объёма пирамиды.';}
  tasks.push({id:'ege-stereo-extra-'+String(i+1).padStart(3,'0'),sourceId,examTopic:'stereometry',topic:5,level:1,title:title+' · вариант '+(k+1),question,answer,hints:[plan,'Сверь величины из условия с элементами на чертеже.'],steps,review:{plan,verify:steps[2],trap:'Обрати внимание, какая величина требуется в ответе.'},figure:{solid,curves:[]},exam:'ege',domain:'math',grade:11,subject:'geometry',topicName:'Стереометрия',unit:null,challenge:true,goal:'ЕГЭ · стереометрия',source:{name:'Решу ЕГЭ',id:sourceId,type:'стереометрия',url:'https://math-ege.sdamgia.ru/problem?id='+sourceId,note:'Авторский вариант по тематике источника; чертёж и разбор — Матклуб.'}});
 }
})();
